 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--autoplay-policy=no-user-gesture-required']);page=b.new_page();page.goto('http://127.0.0.1:8000/');result=page.evaluate('''async()=>{const {answerStripSVG}=await import('./cbse-mcq-print.js');const {scanResponsePhoto,bubblePoint}=await import('./cbse-mcq-scan.js');const canvas=document.createElement('canvas');canvas.width=500;canvas.height=140;const svg=answerStripSVG(1,0,true,true,true),img=new Image();img.src='data:image/svg+xml;base64,'+btoa(new XMLSerializer().serializeToString(svg));await img.decode();const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,500,140);ctx.drawImage(img,0,0);const blankRead=scanResponsePhoto(canvas,1,{compact:true}).responses[0]==='';const empty=document.createElement('canvas');empty.width=500;empty.height=140;empty.getContext('2d').fillStyle='white';empty.getContext('2d').fillRect(0,0,500,140);let noCircleRejected=false;try{scanResponsePhoto(empty,1,{compact:true});}catch{noCircleRejected=true;}const point=bubblePoint(0,1);ctx.fillStyle='black';ctx.beginPath();ctx.arc(point.x,point.y,9,0,Math.PI*2);ctx.fill();const narrow=scanResponsePhoto(canvas,1,{compact:true});const rotated=document.createElement('canvas');rotated.width=140;rotated.height=500;const r=rotated.getContext('2d');r.translate(140,0);r.rotate(Math.PI/2);r.drawImage(canvas,0,0);const sideways=scanResponsePhoto(rotated,1,{compact:true});window.cameraCanvas=canvas;return {blankRead,noCircleRejected,narrow:narrow.responses,sideways:sideways.responses};}''');assert result=={'blankRead':True,'noCircleRejected':True,'narrow':['B'],'sideways':['B']},result
